        axis1.setLabelPaint(Color.BLACK);
        axis2.setLabelPaint(Color.WHITE);
        assertFalse(axis1.equals(axis2));
        axis1.setLabelPaint(Color.BLACK);
        axis2.setLabelPaint(Color.BLACK);

